// Faded Worked Examples kit (We Do phase, after Section 6)
function checkFaded(exId) {
  const card = document.querySelector('[data-faded-id="' + exId + '"]');
  const blanks = card.querySelectorAll('.faded-blank');
  let allCorrect = true, attempted = 0;
  blanks.forEach(b => {
    b.classList.remove('correct', 'incorrect');
    if (b.value.trim() === '') return;
    attempted++;
    const norm = s => (s || '').trim().toLowerCase().replace(/\s+/g, '');
    if (norm(b.value) === norm(b.dataset.expected)) {
      b.classList.add('correct');
    } else {
      b.classList.add('incorrect');
      allCorrect = false;
    }
  });
  const status = document.getElementById('status-' + exId);
  if (attempted === 0) {
    status.textContent = 'Fill in the blanks first.';
  } else if (attempted < blanks.length) {
    status.textContent = `${attempted}/${blanks.length} attempted: keep going.`;
  } else if (allCorrect) {
    status.textContent = '✓ All correct.';
  } else {
    status.textContent = '✗ Some incorrect: check what is left in the bag before each draw.';
  }
}
function revealFaded(exId) {
  const card = document.querySelector('[data-faded-id="' + exId + '"]');
  card.querySelectorAll('.faded-blank').forEach(b => {
    b.value = b.dataset.expected;
    b.classList.add('correct');
  });
  document.getElementById('status-' + exId).textContent = 'Answer shown.';
}

// Hinge Question kit
function pickHingeOption(btn) {
  if (btn.classList.contains('dimmed')) return;
  const isCorrect = btn.dataset.correct === 'true';
  btn.classList.add('selected', isCorrect ? 'correct' : 'incorrect');
  document.querySelectorAll('.hinge-opt').forEach(o => { if (o !== btn) o.classList.add('dimmed'); });
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
  const fbId = btn.dataset.feedbackId;
  if (fbId) document.getElementById(fbId).classList.add('visible');
}
function resetHinge() {
  document.querySelectorAll('.hinge-opt').forEach(o => o.classList.remove('selected', 'correct', 'incorrect', 'dimmed'));
  document.querySelectorAll('.hinge-feedback').forEach(f => f.classList.remove('visible'));
}

// Place each strategy section in its phase: faded examples after the We Do (6), hinge after the Quick check (7)
(function () {
  const faded = document.getElementById('fadedSection');
  const wd = document.getElementById('weDoGrid');
  if (faded && wd) wd.closest('section').after(faded);
  const hinge = document.getElementById('hingeSection');
  const cp = document.getElementById('checkpointGrid');
  if (hinge && cp) cp.closest('section').after(hinge);
})();

// Topic-specific instructions for the frame's fixed section text
(function () {
  const set = (sel, html) => { const el = document.querySelector(sel); if (el) el.innerHTML = html; };
  const m = document.getElementById('matchArea');
  const md = m && m.parentElement.querySelector('.sec-desc');
  if (md) md.textContent = 'Click a path, then click its probability. All five come from a bag of 3 red and 2 blue counters, or from three coins. There are five matching pairs.';
  const wd = document.getElementById('weDoGrid');
  const tip = wd && wd.parentElement.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> the tree records what is left at every stage, so the changing totals (10, then 9, then 8) are never forgotten. Use the same routine in the You do practice: <strong>label the branches → multiply along each path you need → add those paths</strong>.';
  set('#tier1-body .sec-desc', 'Coins, dice, spinners and a bag of 4 red and 6 blue counters. Type a whole number or a fraction such as <code>2/15</code>. Equivalent fractions such as <code>12/90</code> are accepted too.');
  set('#tier2-body .sec-desc', 'Three-step trees, chocolates, club members and cards. Sketch the tree on paper, then type a fraction such as <code>5/33</code>.');
  set('#tier3-body .sec-desc', 'The ace-king-queen problem and the café lucky draw. Type a fraction, or a whole number of dollars (no $ needed).');
})();
